diff --git a/js/unit-tests/test_createBugFixBatchEpic.js b/js/unit-tests/test_createBugFixBatchEpic.js
index 39b23a30..92b59389 100644
--- a/js/unit-tests/test_createBugFixBatchEpic.js
+++ b/js/unit-tests/test_createBugFixBatchEpic.js
@@ -247,3 +247,48 @@ suite('createBugFixBatchEpic', function() {
     });

 });
+
+suite('createBugFixBatchEpic.extractIssues', function() {
+    function loadModule_() {
+        return loadCreateBugFixBatchEpic({});
+    }
+
+    test('returns [] for null, undefined and empty input', function() {
+        var extractIssues = loadModule_().extractIssues;
+        assert.deepEqual(extractIssues(null), []);
+        assert.deepEqual(extractIssues(undefined), []);
+        assert.deepEqual(extractIssues(''), []);
+    });
+
+    test('returns the input array as-is', function() {
+        var arr = [{ key: 'BUG-1' }, { key: 'BUG-2' }];
+        assert.deepEqual(loadModule_().extractIssues(arr), arr);
+    });
+
+    test('parses a JSON string holding an array', function() {
+        assert.deepEqual(loadModule_().extractIssues('[{"key":"BUG-1"}]'), [{ key: 'BUG-1' }]);
+    });
+
+    test('returns [] for an invalid JSON string', function() {
+        assert.deepEqual(loadModule_().extractIssues('not-json{'), []);
+    });
+
+    test('extracts issues, results and data containers from an object', function() {
+        var extractIssues = loadModule_().extractIssues;
+        assert.deepEqual(extractIssues({ issues: ['i1', 'i2'] }), ['i1', 'i2']);
+        assert.deepEqual(extractIssues({ results: ['r1'] }), ['r1']);
+        assert.deepEqual(extractIssues({ data: ['d1', 'd2'] }), ['d1', 'd2']);
+    });
+
+    test('prefers results over data when both are present (pinned order)', function() {
+        var value = { data: ['d'], results: ['r'] };
+        assert.deepEqual(loadModule_().extractIssues(value), ['r']);
+    });
+
+    test('returns [] when no known container key holds an array', function() {
+        var extractIssues = loadModule_().extractIssues;
+        assert.deepEqual(extractIssues({ total: 5 }), []);
+        assert.deepEqual(extractIssues('{"total":5}'), []);
+        assert.deepEqual(extractIssues(42), []);
+    });
+});
diff --git a/js/unit-tests/test_dfManager.js b/js/unit-tests/test_dfManager.js
index acc70c50..109f03d2 100644
--- a/js/unit-tests/test_dfManager.js
+++ b/js/unit-tests/test_dfManager.js
@@ -326,3 +326,55 @@ suite('dfManager', function() {
         assert.equal(report.anomalies[0].prNumber, 42);
     });
 });
+
+suite('dfManager.asArray', function() {
+    function loadDf() {
+        return makeDfManager().module;
+    }
+
+    test('returns [] for falsy input', function() {
+        var asArray = loadDf().asArray;
+        assert.deepEqual(asArray(null), []);
+        assert.deepEqual(asArray(undefined), []);
+        assert.deepEqual(asArray(0), []);
+        assert.deepEqual(asArray(''), []);
+        assert.deepEqual(asArray(false), []);
+    });
+
+    test('returns the input array as-is', function() {
+        var arr = [{ key: 'TS-1' }, { key: 'TS-2' }];
+        assert.deepEqual(loadDf().asArray(arr), arr);
+    });
+
+    test('unwraps a values container', function() {
+        assert.deepEqual(loadDf().asArray({ values: ['a', 'b'] }), ['a', 'b']);
+    });
+
+    test('unwraps an items container', function() {
+        assert.deepEqual(loadDf().asArray({ items: ['x'] }), ['x']);
+    });
+
+    test('unwraps a workflow_runs container', function() {
+        assert.deepEqual(loadDf().asArray({ workflow_runs: [{ id: 1 }] }), [{ id: 1 }]);
+    });
+
+    test('unwraps a result container', function() {
+        assert.deepEqual(loadDf().asArray({ result: ['r1', 'r2'] }), ['r1', 'r2']);
+    });
+
+    test('prefers values over later container keys', function() {
+        var value = { values: ['v'], items: ['i'], workflow_runs: ['w'], result: ['r'] };
+        assert.deepEqual(loadDf().asArray(value), ['v']);
+    });
